tool_calls.arguments:
{"command": "cd /tmp && cp <(kubectl get deploy app -n restricted-app -o yaml) deploy-orig.yaml && cat > patch.json <<'EOF'
{
  "spec": {
    "template": {
      "spec": {
        "securityContext": {
          "runAsNonRoot": true,
          "runAsUser": 1000,
          "seccompProfile": { "type": "RuntimeDefault" }
        },
        "containers": [
          {
            "name": "app",
            "securityContext": {
              "allowPrivilegeEscalation": false,
              "capabilities": { "drop": ["ALL"] }
            }
          }
        ]
      }
    }
  }
}
EOF
kubectl patch deploy app -n restricted-app --type=strategic -p "$(cat patch.json)""}

